async function fetchBuffer(url){let last=0;for(let i=0;i<6;i++){const r=await fetch(url,{headers:{'user-agent':'History-Go-place-production/1.0'}});last=r.status;if(r.ok)return Buffer.from(await r.arrayBuffer());if(![429,500,502,503,504].includes(r.status))break;await new Promise(res=>setTimeout(res,1000*(i+1)));}throw new Error(`image fetch failed ${last}: ${url}`);}
async function outputImage({url,file,width,height,fit='cover',position='centre'}){const p=path.join(root,file);fs.mkdirSync(path.dirname(p),{recursive:true});await sharp(await fetchBuffer(url)).rotate().resize(width,height,{fit,position,withoutEnlargement:false}).webp({quality:84,effort:5}).toFile(p);}
await outputImage({url:urls.mainAsset,file:'bilder/places/romsaås.webp',width:1200,height:675});
