const story={id:'st_romsaås_seks_grender_1970_1974',quality_profile:'episode_v1',type:'turning_point',title:'Seks grender legges inn i skogen',year:1970,place_id:placeId,person_id:null,summary:'I første halvdel av 1970-årene ble Romsås bygd ut som seks boliggrender med gangsystemer, senter og T-bane i et kupert skogsterreng.',story:'Da Oslo kommune tok kontroll over store arealer på Romsås i 1960-årene, åpnet det for en mer samlet utbygging enn den eldre spredte bosettingen hadde gitt. Romsåsteamet planla seks grender mellom koller og skog, med blokkene plassert i varierende høyder.\n\nUtbyggingen skjøt fart omkring 1970. I stedet for å la bilveiene skjære gjennom alle boliggrendene, ble mye av interntrafikken organisert som gangforbindelser, mens bilene i stor grad ble holdt ved ytterkanten. Romsås senter åpnet i 1972 og ga området et lokalt servicepunkt.\n\nI 1974 åpnet T-banestasjonen i fjellet. Dermed ble den terrengtilpassede boligplanen koblet direkte til Grorudbanen. Romsås ble ikke stående uendret; senere park-, kirke- og stasjonslag viser hvordan et helhetlig planlagt område fortsetter å bli omformet.',episode:{actors:['Oslo kommune','Romsåsteamet','beboere og lokale institusjoner'],date:'ca. 1970–1974',action:'Seks boliggrender, senter og kollektivtilkobling ble realisert i et samlet utbyggingsforløp.',consequence:'Romsås fikk en varig fysisk grunnstruktur med terrengtilpassede boliggrender og trafikkskilte forbindelser.'},sources:[{title:'Oslo byleksikon – Romsås',url:urls.byleksikon},{title:'Oslo kommune – Groruddalen',url:urls.municipality},{title:'Sporveien – Romsås',url:urls.station}],tags:['Romsås','drabantby','1970-tallet','byplanlegging'],related_people:[],related_places:['grorud'],score:{narrative:3,historical:3,source:4,play_value:3,originality:3,total:16},arc:{start:'Kommunen legger grunnlaget for samlet utbygging.',middle:'Seks grender og et lokalt senter bygges ut.',end:'T-banen kobler den nye drabantbyen til resten av byen.'}};
