const test=`import assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport test from 'node:test';\nimport { validatePacket } from '../scripts/validate-place-description-production-v4_2.mjs';\nconst root=process.cwd();const read=f=>JSON.parse(fs.readFileSync(path.join(root,f),'utf8'));const place=read('${placeFile}');const quiz=read('${quizFile}');const production=read('${packetFile}');const runtime=read('data/runtime/place-open/romsaås.json');const language=read('${languageFile}');const leksikon=read('${leksikonFile}');const audit=read('reports/place-production/romsaås-phase1-24-gate-audit-v1.json');\ntest('Romsås has exact four standard collections and preserved geometry',()=>{assert.equal(place.lat,59.9664278);assert.equal(place.lon,10.89815);assert.equal(place.production_status,'complete');assert.equal(place.fagverk.status,'curated');assert.deepEqual(place.place_card_profile.collection_ids,['people','objects','brands','structures']);assert.deepEqual(place.related_people_ids,['don_martin']);assert.equal(place.objects.length,1);assert.equal(place.structures.length,1);});\ntest('Romsås replaces legacy 3x5 with unique 4x7',()=>{const qs=quiz.sets.flatMap(s=>s.questions);assert.equal(fs.existsSync('${legacyQuizFile}'),false);assert.equal(quiz.sets.length,4);assert.ok(quiz.sets.every(s=>s.questions.length===7));assert.equal(qs.length,28);assert.equal(new Set(qs.map(q=>q.question)).size,28);assert.ok(qs.slice(0,14).every(q=>!q.method_id&&!q.theory_ref));assert.ok(qs.slice(21,24).every(q=>q.method_id));assert.ok(qs.some(q=>q.theory_ref?.topic_hook_id==='bolig_boligtyper'&&q.thinker_id==='david_harvey'&&q.work==='Rebel Cities'));assert.ok(qs.every(q=>q.source_origin==='external'));const manifest=read('data/quiz/manifest.json');assert.equal((manifest.targets||[]).filter(e=>e.targetId==='romsaås').length,1);});\ntest('Romsås learning layers are complete',()=>{assert.equal(leksikon[0].chronology.length,10);assert.equal(language.entries.length,6);assert.equal(runtime.stories.length,1);assert.equal(runtime.lesespor.length,4);assert.ok(runtime.people.some(p=>p.id==='don_martin'));assert.ok(runtime.brands.some(b=>b.id==='obos'));});\ntest('Romsås description packet validates',()=>{const result=validatePacket({packet:production,place,packetFile:'${packetFile}',now:new Date('2026-09-03T12:00:00Z')});assert.deepEqual(result.issues,[]);});\ntest('Romsås quality gate is 30/30 with no blocker',()=>{const dimensions=Object.values(audit.quality_score).filter(v=>v&&typeof v==='object'&&'score' in v);assert.equal(dimensions.length,6);assert.ok(dimensions.every(x=>x.score===5));assert.equal(audit.quality_score.total,30);assert.equal(audit.quality_score.unresolved_blockers,0);assert.equal(place.module_audit.for_na.status,'source_bounded_holdback');});\n`;
